# Enem 2015, 2º dia, caderno azul: Linguagens (questões 91 a 135 do caderno). Duas provas no site:
# enem-2015-linguagens-ingles (1–5 = inglês) e enem-2015-linguagens-espanhol (1–5 = espanhol); 6–45 = questões 96–135, iguais nas duas.
# Letras de canção e poemas posteriores a 1929 só como imagem (Q91 e Q91-es, Q99, Q100, Q101, Q104, Q109, Q116, Q119, Q126, Q129); Bilac (1904) transcrito.
import sys, pathlib, re
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent / "tools"))
from enem_aj import carregar_enem, enunciado_enem, paragrafos_enem

D = carregar_enem("enem-2015-dia2-azul")
p = lambda *xs: "".join(f"<p>{x}</p>" for x in xs)


def figs(*pares):
    return [{"arquivo": a, "alt": t} for a, t in pares]


def poema(n, alt, arq=None):
    """Poema ou letra como imagem: [[fig:1]], a referência e o comando."""
    par = paragrafos_enem(D[n])
    fonte = [x for t, x in par if t == "fonte"][-1]
    cmd = [x for t, x in par if t == "p"][-1]
    arq = arq or "q" + str(n).replace("-", "")
    return {"enunciado": f'[[fig:1]]<p class="fonte">{fonte}</p>' + p(cmd), "imagens": figs((arq, alt))}


def Q_(n, materia, assunto, expl, tags=(), trocas=(), extra=None, alts=None):
    q = {"materia": materia, "assunto": assunto, "area": "Linguagens", "tags": list(tags), "numeroOriginal": int(str(n).split("-")[0]),
         "enunciado": enunciado_enem(D[n], trocas), "alternativas": dict(alts or D[n]["alternativas"]), "imagens": [], "explicacao": expl}
    if extra: q.update(extra)
    q["alternativas"] = {k: re.sub(r"\s*LINGUAGENS, CÓDIGOS.*$", "", v).replace("cana-de- açúcar", "cana-de-açúcar").replace("afro- brasileiras", "afro-brasileiras") for k, v in q["alternativas"].items()}
    return q


